    limitNum: null,
    singleMode: false,
    countMode: false,
    headOnly: false,
    orderBy: null,
    orderAsc: true,
  };

  const apply = () => {
    let rows = load(table);
    ctx.filters.forEach(f => {
      try {
        if (f.type === 'eq')      rows = rows.filter(r => r[f.col] === f.val);
