        else if (f.type === 'is')  rows = rows.filter(r => r[f.col] === null);
        else if (f.type === 'in')  rows = rows.filter(r => f.vals.includes(r[f.col]));
      } catch {}
    });
    if (ctx.orderBy) {
      rows.sort((a, b) => (a[ctx.orderBy] > b[ctx.orderBy] ? 1 : -1) * (ctx.orderAsc ? 1 : -1));
